 function revealResult(){if(window.matchMedia('(max-width:700px)').matches)status.scrollIntoView({behavior:'smooth',block:'nearest'});}
 function downloadText(filename,text,type){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
 function addModeSettings(){
  const group=document.createElement('fieldset');group.className='app-buffer-settings';const legend=document.createElement('legend');legend.textContent='Practice usage mode';group.append(legend);
  const note=document.createElement('p');note.textContent='Selection stays in this walkthrough. It does not change app settings or unlock Pro tools. Captured maps and account details remain fixed.';group.append(note);
  const label=document.createElement('label');label.textContent='Mode';const select=document.createElement('select');select.setAttribute('aria-label','Practice usage mode');const empty=document.createElement('option');empty.value='';empty.textContent='Choose a mode…';select.append(empty);
  Object.entries(usageModes).forEach(([key,mode])=>{const option=document.createElement('option');option.value=key;option.textContent=mode.name;select.append(option);});select.value=practiceMode||'';label.append(select);group.append(label);
  const details=document.createElement('p');details.setAttribute('data-mode-details','');group.append(details);
  const tryButton=document.createElement('button');tryButton.type='button';tryButton.className='app-record-download';tryButton.textContent='Try a related workflow';tryButton.onclick=()=>{if(practiceMode)show(usageModes[practiceMode].screen);};group.append(tryButton);
  const back=document.createElement('button');back.type='button';back.className='app-record-download';back.textContent='Return to Settings';back.onclick=()=>show('settings');group.append(back);
  const update=()=>{const mode=usageModes[practiceMode];details.textContent=mode?`${mode.name}: ${mode.summary} Preset coordinates: ${mode.coordinate}. Distance: ${mode.distance}.`:'Choose a mode on the captured screen or in the menu.';tryButton.disabled=!mode;};select.onchange=()=>{practiceMode=select.value||null;update();};update();status.append(group);
 }
 function addTrackReport(){
  const group=document.createElement('fieldset');group.className='app-buffer-settings';const legend=document.createElement('legend');legend.textContent='Captured track report';group.append(legend);
  const note=document.createElement('p');note.textContent='These are values displayed in the actual app capture. The full 34-point track is unavailable; statistics are not recalculated from the endpoints. Elevation zeros are copied as shown, without verified measured altitude.';group.append(note);
  const label=document.createElement('label');label.textContent='Report units';const select=document.createElement('select');select.setAttribute('aria-label','Practice track report units');[['metric','Metric (as captured)'],['imperial','Imperial (converted)']].forEach(([key,text])=>{const option=document.createElement('option');option.value=key;option.textContent=text;select.append(option);});select.value=reportUnits;label.append(select);group.append(label);
  const table=document.createElement('table');table.className='app-report-table';const caption=document.createElement('caption');caption.textContent=MapNeroCapturedReport.title;table.append(caption);const body=document.createElement('tbody');table.append(body);group.append(table);
  const feedback=document.createElement('p');feedback.setAttribute('role','status');feedback.dataset.reportFeedback='';group.append(feedback);
  const render=()=>{body.replaceChildren();MapNeroCapturedReport.rows(reportUnits).forEach(([name,value])=>{const row=document.createElement('tr');const th=document.createElement('th');th.scope='row';th.textContent=name;const td=document.createElement('td');td.textContent=value;row.append(th,td);body.append(row);});feedback.textContent='';};select.onchange=()=>{reportUnits=select.value;render();};render();
  const download=document.createElement('button');download.type='button';download.className='app-record-download';download.textContent='Download captured report PDF';download.onclick=()=>act('reportDownload');group.append(download);status.append(group);
 }
