  if(action==='storeSearch'){storeController?.focusSearch();return;}
  if(action.startsWith('storeCategory:')){storeController?.chooseCategory(action.slice(14));return;}
  if(action==='importFiles'){mapImportController?.chooseFiles();return;}
  if(action==='importPhoto'){mapImportController?.choosePhoto();return;}
