  if(action==='reportDownload'){downloadText(`mapnero-captured-track-report-${reportUnits}.pdf`,MapNeroCapturedReport.createPDF(reportUnits),'application/pdf');const feedback=status.querySelector('[data-report-feedback]');if(feedback)feedback.textContent=`${reportUnits==='imperial'?'Imperial':'Metric'} practice report downloaded. It contains captured statistics, not the full GPS track.`;revealResult();return;}
  if(action==='reportHelp'){revealResult();return;}

